SELECT COUNT(*) FROM stars s WHERE EXISTS (
    SELECT 1 FROM planets p 
    WHERE p.hostlink = s.stellarref 
    AND p.discmethod IN ('Transit', 'TR', 'Transit Method', 'Photometry', 'Photometric')
)
AND NOT EXISTS (
    SELECT 1 FROM planets p 
    WHERE p.hostlink = s.stellarref 
    AND p.discmethod IN ('RadVel', 'RV', 'RV Method', 'Radial Velocity', 'Doppler')
);

SELECT AVG(POWER(CAST(s.stellarprops->'physical'->>'Radius_Value' AS numeric), 2) * POWER(CAST(s.stellarprops->'physical'->>'Temp_Value' AS numeric) / 5778, 4)) AS avg_luminosity
FROM stars s
WHERE s.stellarprops->'physical'->>'Radius_Value' IS NOT NULL
AND s.stellarprops->'physical'->>'Temp_Value' IS NOT NULL
AND EXISTS (
    SELECT 1 FROM planets p WHERE p.hostlink = s.stellarref AND p.discmethod IN ('Transit', 'TR', 'Transit Method', 'Photometry', 'Photometric')
)
AND NOT EXISTS (
    SELECT 1 FROM planets p WHERE p.hostlink = s.stellarref AND p.discmethod IN ('RadVel', 'RV', 'RV Method', 'Radial Velocity', 'Doppler')
);

SELECT ROUND(CAST(AVG(CAST(POWER(CAST(s.stellarprops->'physical'->>'Radius_Value' AS numeric), 2) * POWER(CAST(s.stellarprops->'physical'->>'Temp_Value' AS numeric) / CAST(5778 AS numeric), 4) AS numeric)), 4)
FROM stars s
WHERE s.stellarprops->'physical'->>'Radius_Value' IS NOT NULL
AND s.stellarprops->'physical'->>'Temp_Value' IS NOT NULL
AND EXISTS (
    SELECT 1 FROM planets p WHERE p.hostlink = s.stellarref AND p.discmethod IN ('Transit', 'TR', 'Transit Method', 'Photometry', 'Photometric')
